// Cuánto rinde de verdad un enlace Wi-Fi: modelo simplificado estilo 802.11a (tiempos en µs).
const RANURA = 9, SIFS = 16, DIFS = SIFS + 2 * RANURA;   // DIFS = 34 µs
const PREAMBULO = 20, SIMBOLO = 4;                        // 16 µs de preámbulo + 4 µs de campo SIGNAL; símbolo de 4 µs
const BACKOFF_MEDIO = 7.5 * RANURA;                       // espera al azar de 0 a 15 ranuras: 7,5 en promedio

const velocidadAck = mbps => (mbps >= 24 ? 24 : mbps >= 12 ? 12 : 6);   // el ACK va a una velocidad básica

function aire(bytes, mbps) {                              // tiempo que ocupa una transmisión
  const simbolos = Math.ceil((16 + 8 * bytes + 6) / (mbps * SIMBOLO));  // 16 bits de servicio y 6 de cola
  return PREAMBULO + simbolos * SIMBOLO;
}

function ciclo(cargaIP, mbps, tramas = 1) {               // un intento completo: esperar, enviar, confirmar
  const mpdu = cargaIP + 8 + 24 + 4;                      // + LLC/SNAP + cabecera MAC + FCS
  const datos = tramas === 1 ? aire(mpdu, mbps)
    : PREAMBULO + Math.ceil((16 + 8 * mpdu * tramas + 6) / (mbps * SIMBOLO)) * SIMBOLO;   // agregadas: un solo preámbulo
  return DIFS + BACKOFF_MEDIO + datos + SIFS + aire(14, velocidadAck(mbps));
}

const util = (carga, mbps, tramas = 1) => (carga * tramas * 8) / ciclo(carga, mbps, tramas);   // bits/µs = Mb/s

console.log('1500 bytes de IP por trama; una sola estación, sin errores ni vecinos');
for (const mbps of [6, 24, 54, 150, 600, 1200]) {
  const r = util(1500, mbps);
  console.log(`anunciado ${String(mbps).padStart(4)} Mb/s -> útil ${r.toFixed(1).padStart(5)} Mb/s (${(100 * r / mbps).toFixed(0)} %)`);
}
const agregado = util(1500, 600, 16);
console.log(`600 Mb/s con 16 tramas por envío -> útil ${agregado.toFixed(1)} Mb/s (${(100 * agregado / 600).toFixed(0)} %)`);

// Dos estaciones en el mismo canal: CSMA/CA les da el mismo número de turnos, no el mismo tiempo.
const ronda = ciclo(1500, 54) + ciclo(1500, 6);
console.log(`\nuna a 54 y otra a 6 Mb/s: cada una logra ${(1500 * 8 / ronda).toFixed(1)} Mb/s (la de 54 sola lograba ${util(1500, 54).toFixed(1)})`);
